import unittest
from candidate import iscube

class TestIsCube(unittest.TestCase):
    def test_is_cube_true_positive(self):
        self.assertTrue(iscube(1))

    def test_is_cube_true_negative(self):
        self.assertTrue(iscube(-1))

    def test_is_cube_true_zero(self):
        self.assertTrue(iscube(0))

    def test_is_cube_true_power_of_three(self):
        self.assertTrue(iscube(27))

    def test_is_cube_false_not_power_of_three(self):
        self.assertFalse(iscube(2))

    def test_is_cube_false_large_number(self):
        self.assertFalse(iscube(180))

    def test_is_cube_true_large_cube(self):
        self.assertTrue(iscube(4096))

    def test_is_cube_true_cube_of_negative(self):
        self.assertTrue(iscube(-125))

    def test_is_cube_true_cube_of_zero(self):
        self.assertTrue(iscube(0))

    def test_is_cube_false_not_integer_cube(self):
        with self.assertRaises(TypeError):
            iscube(2.5)

if __name__ == '__main__':
    unittest.main()
